 nhtsaGet("recalls/recallsByVehicle",make,model,function(rs){each(rs,function(r){out.push(recallFault({id:"nhtsa-"+(r.NHTSACampaignNumber||uid()),title:H(r.Component||"Composant"," — ",String(r.Summary||"Rappel").slice(0,90)),sys:r.Component||"Campagne",ref:uniq([r.NHTSACampaignNumber,r.ManufacturerCampaignNumber].filter(Boolean)),url:H("https://www.nhtsa.gov/recalls?nhtsaId=",r.NHTSACampaignNumber),targets:tg,meca:r.Summary||"",cons:[r.Consequence||""],ind:[r.Remedy||""],source:"nhtsa-recall"}));});fin();});
