function huntRappelConso(sel,cb){var base="https://data.economie.gouv.fr/api/explore/v2.1/catalog/datasets/rappelconso-v2-gtin-espaces/records",bt=nrm(String(sel.brand.name).split(" ")[0]),mt=nrm(sel.model?sel.model.name:""),out=[],off=0;function step(){if(off>=600){cb(out);return;}jget(H(base,"?where=",encodeURIComponent('categorie_produit="automobiles et moyens de déplacement"'),"&limit=100&offset=",off),9000,function(j){var res=(j&&j.results)||[];off+=100;each(res,function(r){var mk=nrm(r.marque_produit||""),mo=nrm(H(r.modeles_ou_references," ",r.libelle));if(bt&&mk.indexOf(bt)<0)return;if(mt&&mo.indexOf(mt)<0&&nrm(r.libelle||"").indexOf(mt)<0)return;var feu=/incendie|feu|flamme|inflamm/i.test(H(r.motif_rappel,r.risques_encourus));out.push(recallFault({id:H("rc-",r.numero_fiche||uid()),title:String(r.libelle||r.motif_rappel||"Rappel").slice(0,200),sys:r.sous_categorie_produit||"Campagne",grav:feu?"critique":"eleve",ref:[H("FICHE-",r.numero_fiche)],url:r.lien_vers_la_fiche_rappel||"",targets:{E:sel.engine?[sel.engine.id]:[],M:sel.model?[sel.model.id]:[],B:sel.brand?[sel.brand.id]:[],P:null,Y:null},meca:r.motif_rappel||"",cons:[r.risques_encourus||""],ind:[],source:"rappelconso"}));});if(!res.length){cb(out);return;}setTimeout(step,80);});}step();}
