function recallHunt(cb){var sel=selected();if(!sel.brand||!sel.model){toast("Sélectionne marque + modèle.");return;}if(S.hunting){toast("⏳ Recherche en cours.");return;}S.hunting=true;S.huntStop=false;setHunt("⏳","NHTSA + RappelConso…");huntNhtsa(sel,function(a){if(S.huntStop){S.hunting=false;setHunt("⚠️","Interrompu.");if(cb)cb();return;}huntRappelConso(sel,function(b){var all=a.concat(b),added=KDB.addFaults(all),i;for(i=0;i<all.length;i++)S.recalls.push(all[i]);persistRecalls();S.hunting=false;setHunt("✅",H("+",added," officielle(s)"));chk("recall","ok",H(S.recalls.length," rappels/TSB"));fillFilters();renderResults();renderIdFaults();stats();toast(H("🛰️ +",added," rappels/TSB pour ",sel.brand.name," ",sel.model.name,"."));if(cb)cb();});});}
