function matchBracket(txt,start){var stack=[],i,ch,inStr=false,q="",escp=false,o,lim=Math.min(txt.length,start+2500000);for(i=start;i<lim;i++){ch=txt.charAt(i);if(inStr){if(escp)escp=false;else if(ch==="\\")escp=true;else if(ch===q)inStr=false;continue;}if(ch==='"'||ch==="'"||ch==="`"){inStr=true;q=ch;continue;}if(ch==="{"||ch==="[")stack.push(ch);else if(ch==="}"||ch==="]"){o=stack.pop();if(!o)return -1;if((o==="{"&&ch!=="}")||(o==="["&&ch!=="]"))return -1;if(stack.length===0)return i;}}return -1;}
function jsToJson(s){var res="",i,ch,inStr=false,q="",escp=false;for(i=0;i<s.length;i++){ch=s.charAt(i);if(inStr){if(escp){res+=ch;escp=false;continue;}if(ch==="\\"){res+=ch;escp=true;continue;}if(ch===q){res+='"';inStr=false;continue;}if(q==="'"&&ch==='"'){res+='\\"';continue;}if(ch==="\n"||ch==="\r"){res+=" ";continue;}res+=ch;continue;}if(ch==="'"||ch==='"'){inStr=true;q=ch;res+='"';continue;}res+=ch;}res=res.replace(/([{,]\s*)([A-Za-z_$][\w$]*)\s*:/g,'$1"$2":');res=res.replace(/,\s*([}\]])/g,"$1");return res;}
function tryParse(raw){var v=null;try{v=JSON.parse(raw);if(v)return v;}catch(e){}try{v=JSON.parse(jsToJson(raw));if(v)return v;}catch(e){}return null;}
function blocks(txt,cb){var re=/[A-Za-z_$][\w$]*/g,m,seen={},start,end,raw,v,j,depth,ch,KW=/^(marques|modeles|motorisations|puissances|cylindree|brands|models|engines|powers|vehicules|vehicles|pannes|fiches|defauts|faults|catalogue|data|items|list|rows|records|results|dtc|codes|rappels|campagnes)$/i;while((m=re.exec(txt))){if(!KW.test(m[0]))continue;start=-1;depth=0;for(j=m.index;j>=0&&j>m.index-8000;j--){ch=txt.charAt(j);if(ch==="}"||ch==="]")depth++;else if(ch==="{"||ch==="["){if(depth===0){start=j;break;}depth--;}}if(start<0||seen[start])continue;seen[start]=1;end=matchBracket(txt,start);if(end<0)continue;raw=txt.slice(start,end+1);if(raw.length<20||raw.length>2500000)continue;v=tryParse(raw);if(v)cb(v);}}
function strArrays(txt,cb){var i=0,n=0,lim=Math.min(txt.length,5000000),k,end,raw,v,ctx;while(i<lim-1&&n<800){if(txt.charAt(i)==="["){k=i+1;while(k<lim&&/\s/.test(txt.charAt(k)))k++;if(txt.charAt(k)==='"'||txt.charAt(k)==="'"){end=matchBracket(txt,i);if(end>0){raw=txt.slice(i,end+1);if(raw.length>10&&raw.length<300000){v=tryParse(raw);if(v&&Object.prototype.toString.call(v)==="[object Array]"&&v.length>=3){ctx=txt.slice(Math.max(0,i-90),i);cb(v,ctx);n++;}}i=end+1;continue;}}}i++;}}
function ingestBlob(txt,source){var n={faults:0,vehicles:0},r,parsed=tryParse(txt);function add(v){r=KDB.ingestExternal(v,source);n.faults+=r.faults;n.vehicles+=r.vehicles;}if(parsed)add(parsed);blocks(txt,function(v){add(v);});strArrays(txt,function(v){add(v);});return n;}
function ingestCsv(txt,source){var ls=txt.split(/\r?\n/);if(ls.length<2)return 0;var head=ls[0].split(/[,;\t]/).map(function(h){return nrm(h);}),objs=[],i,j;for(i=1;i<ls.length&&objs.length<3000;i++){var cells=ls[i].split(/[,;\t]/);if(cells.length<2)continue;var o={};for(j=0;j<head.length;j++)o[head[j]]=trm(cells[j]||"");objs.push(o);}var r=KDB.ingestExternal(objs,source);return r.faults+r.vehicles;}
function ingestText(txt,source){var parts=txt.split(/\n\s*\n/),n=0;each(parts,function(x){var first=trm(x.split("\n")[0]||"");if(x.replace(/\s/g,"").length<40||!first)return;var fo={id:H(source,"-doc-",uid()),title:first.slice(0,140),sys:"Document",grav:"modere",fire:/incendie|feu|flamme/i.test(x),targets:{E:[],M:[],B:[],P:null,Y:null},dtc:x.toUpperCase().match(/[PCBU]\d{4}/g)||[],sym:[],meca:x.slice(0,1500),cons:[],ind:[],chain:"",source:source};KDB.addFaults([fo]);n++;});return n;}
function ingestAnyFile(txt,path,source){var ext=((path||"").match(/\.([a-z0-9]+)$/i)||[,""])[1].toLowerCase();if(ext==="json"){var v=tryParse(txt);if(v){var r=KDB.ingestExternal(v,source);return r.faults+r.vehicles;}return 0;}if(ext==="js"||ext==="mjs"){var n=ingestBlob(txt,source);return n.faults+n.vehicles;}if(ext==="csv")return ingestCsv(txt,source);if(ext==="md"||ext==="txt")return ingestText(txt,source);var b=ingestBlob(txt,source);return b.faults+b.vehicles;}
function ghDefaultBranch(owner,repo,cb){req(H("https://api.github.com/repos/",owner,"/",repo),9000,function(e,r){if(e||!r.ok){cb(null);return;}try{cb(JSON.parse(r.text).default_branch||"main");}catch(x){cb("main");}});}
function ghTree(owner,repo,branch,cb){req(H("https://api.github.com/repos/",owner,"/",repo,"/git/trees/",branch,"?recursive=1"),12000,function(e,r){if(e||!r.ok){cb(e||"tree",null);return;}try{var j=JSON.parse(r.text),out=[];each(j.tree||[],function(t){if(t.type==="blob"&&/\.(json|js|mjs|csv|md|txt)$/i.test(t.path)&&(t.size==null||t.size<4000000))out.push(t.path);});cb(null,out);}catch(x){cb("illisible",null);}});}
