function syncPull(cb){var raw=chanRaw();if(!raw){chk("sync","warn","aucun canal");if(cb)cb();return;}readChanAuto(raw,function(err,st,be){var p,meta,i=0,A,added=0;if(err||!st){chk("sync","warn",err||"vide");if(cb)cb();return;}p=parseChan(raw);if(!p.be||p.be!==be)setChan(p.id,be);A=SYNC[be];if(st.entries&&st.entries.length){KDB.addFaults(st.entries);S.ov.entries=st.entries;}meta=st.photos||[];function adopt(m,u){var ex=false,j;for(j=0;j<S.ov.photos.length;j++)if(S.ov.photos[j].id===m.id)ex=true;if(!ex){S.ov.photos.push({id:m.id,fault:m.fault,cap:m.cap,ts:m.ts,src:"sync"});added++;}if(u)S.photoData[m.id]=u;}function step(){var m,ca,url,key;if(i>=meta.length){if(added)persist();if(st.look){S.look=st.look;applyLook();}if(st.revs&&st.revs.length){each(st.revs,function(s){if(!has(S.revs,s))S.revs.push(s);});save("revs",S.revs);checkRev();}chk("sync","ok",H(A.name," reçu"));fillFilters();renderResults();renderFaults();renderIdFaults();stats();if(cb)cb();return;}m=meta[i];i++;if(m.ref==="key"){ca=S.photoData[m.id];if(ca){adopt(m,null);step();return;}key=m.key||m.id;A.getPh(p.id,key,function(du){if(du){MStore.put(m.id,du,m.cap);adopt(m,du);}else adopt(m,null);step();});return;}url=m.ref==="embed"?((st.embedded||{})[m.id]||""):(m.url||"");if(url){MStore.put(m.id,url,m.cap);adopt(m,url);}else adopt(m,null);step();}step();});}
